/* Arte do guardião: quadros da folha de sprites enviada pelo autor (fundo removido, reduzida a 50%). Gerado, não editar à mão. */
const ARTE_BOSS={"peq": {"w": 33, "h": 34, "f": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]}, "bol": {"w": 90, "h": 48, "f": ["data:image/png;base64,", "data:image/png;base64,"]}, "big": {"w": 151, "h": 122, "f": ["data:image/png;base64,", "data:image/png;base64,"]}, "fraco": {"w": 152, "h": 110, "f": ["data:image/png;base64,"]}};
(function(){for(const k in ARTE_BOSS){const o=ARTE_BOSS[k];o.img=o.f.map(s=>{const i=new Image();i.src=s;return i;});}})();
function bossArte(k,i){const o=ARTE_BOSS[k],m=o.img[i%o.img.length];return m&&m.complete&&m.naturalWidth?m:null;}
